<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientTokenEndpointAuthSigningAlgAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientTokenEndpointAuthSigningAlgAccessor trait.
 *
 * Covers null default, string/VO assignment via withTokenEndpointAuthSigningAlg,
 * getTokenEndpointAuthSigningAlg/tokenEndpointAuthSigningAlg accessors, and isTokenEndpointAuthSigningAlgChanged with/without original.
 */
class TrustedClientTokenEndpointAuthSigningAlgAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTokenEndpointAuthSigningAlg creates a new instance with the TokenEndpointAuthSigningAlg set
     * from a string value, and getTokenEndpointAuthSigningAlg returns the primitive string.
     */
    public function testWithTokenEndpointAuthSigningAlgFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTokenEndpointAuthSigningAlgAccessorUnitTest();

        // Act
        $result = $holder->withTokenEndpointAuthSigningAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getTokenEndpointAuthSigningAlg());
    }
    /**
     * Asserts that withtokenEndpointAuthSigningAlg has access to the value object
     * from a string value, and getTokenEndpointAuthSigningAlg returns the primitive string.
     */
    public function testWithTokenEndpointAuthSigningAlgFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTokenEndpointAuthSigningAlgAccessorUnitTest();

        // Act
        $result = $holder->withTokenEndpointAuthSigningAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->tokenEndpointAuthSigningAlg()->value());
    }
    public function testChangedTokenEndpointAuthSigningAlg(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTokenEndpointAuthSigningAlgAccessorUnitTest();
        $original = $holder->withTokenEndpointAuthSigningAlg('one');
        $same = $holder->withTokenEndpointAuthSigningAlg('one');
        $modified = $holder->withTokenEndpointAuthSigningAlg('other');

        // Act
        $unchanged = $holder->isTokenEndpointAuthSigningAlgChanged();
        $withSame = $original->isTokenEndpointAuthSigningAlgChanged($same);
        $withDiferent = $original->isTokenEndpointAuthSigningAlgChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientTokenEndpointAuthSigningAlgAccessorUnitTest
{
    use TrustedClientTokenEndpointAuthSigningAlgAccessor;
}
